static int rt712_sdca_update_status ( struct sdw_slave * slave , enum sdw_slave_status status ) { struct rt712_sdca_priv * rt712 = dev_get_drvdata ( & slave -> dev ) ; rt712 -> status = status ; if ( status == SDW_SLAVE_UNATTACHED ) { rt712 -> hw_init = false ; } if ( status == SDW_SLAVE_ATTACHED ) { if ( rt712 -> hs_jack ) { sdw_write_no_pm ( rt712 -> slave , SDW_SCP_SDCA_INTMASK1 , SDW_SCP_SDCA_INTMASK_SDCA_0 ) ; sdw_write_no_pm ( rt712 -> slave , SDW_SCP_SDCA_INTMASK2 , SDW_SCP_SDCA_INTMASK_SDCA_8 ) ; } } return rt712_sdca_io_init ( & slave -> dev , slave ) ; } 